import{_ as e,o as t,c as r,a2 as a}from"./chunks/framework.A5mep7Fe.js";const u=JSON.parse('{"title":"🚀 04 · 运维与 DevOps（含 LLMOps 基础设施）","description":"","frontmatter":{},"headers":[],"relativePath":"07-开发岗-前后端与全栈/04-运维与DevOps.md","filePath":"07-开发岗-前后端与全栈/04-运维与DevOps.md","lastUpdated":1786806808000}'),s={name:"07-开发岗-前后端与全栈/04-运维与DevOps.md"};function l(n,o,i,p,c,d){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="🚀-04-·-运维与-devops-含-llmops-基础设施" tabindex="-1">🚀 04 · 运维与 DevOps（含 LLMOps 基础设施） <a class="header-anchor" href="#🚀-04-·-运维与-devops-含-llmops-基础设施" aria-label="Permalink to &quot;🚀 04 · 运维与 DevOps（含 LLMOps 基础设施）&quot;">​</a></h1><blockquote><p>把 AI 应用稳定跑起来、能扩容、可观测、控成本。AI 运维比传统多一层「模型与推理」复杂度。</p></blockquote><hr><h2 id="一、核心考点-通用" tabindex="-1">一、核心考点（通用） <a class="header-anchor" href="#一、核心考点-通用" aria-label="Permalink to &quot;一、核心考点（通用）&quot;">​</a></h2><ul><li><strong>CI/CD</strong>：GitLab CI / GitHub Actions / Jenkins，自动化构建测试部署。</li><li><strong>容器化</strong>：Docker、镜像优化；编排 K8s（Pod/Deployment/HPA）。</li><li><strong>可观测</strong>：日志（ELK）、监控（Prometheus/Grafana）、链路追踪（OpenTelemetry）。</li><li><strong>基础设施即代码</strong>：Terraform / Helm。</li></ul><h2 id="二、ai-专属运维-llmops" tabindex="-1">二、AI 专属运维（LLMOps） <a class="header-anchor" href="#二、ai-专属运维-llmops" aria-label="Permalink to &quot;二、AI 专属运维（LLMOps）&quot;">​</a></h2><ul><li><strong>模型服务部署</strong>：vLLM/TensorRT-LLM 推理服务、GPU 资源调度、自动扩缩容。</li><li><strong>GPU 运维</strong>：显存监控、多卡调度、利用率优化、成本（按卡时计费）。</li><li><strong>向量库运维</strong>：Milvus/PGVector 集群、索引维护、备份。</li><li><strong>Prompt/模型版本管理</strong>：Registry、灰度、回滚。</li><li><strong>成本可观测</strong>：token 消耗、调用分布、异常高成本告警。</li></ul><h2 id="三、高频追问" tabindex="-1">三、高频追问 <a class="header-anchor" href="#三、高频追问" aria-label="Permalink to &quot;三、高频追问&quot;">​</a></h2><p><strong>Q1：推理服务怎么扩缩容？</strong></p><blockquote><p>按并发/GPU 利用率自动扩 Pod；用连续批处理提吞吐；显存是瓶颈，需监控 KV Cache 与并发；模型大时用多副本 + 负载均衡。</p></blockquote><p><strong>Q2：AI 应用的可观测比普通应用多了什么？</strong></p><blockquote><p>多了模型层指标：token 用量、延迟分解（首 token/总耗时）、幻觉率、评测分、Prompt 版本、降级次数、成本。这些直接关系体验与花费。</p></blockquote><hr><p>➡️ 下一步：<a href="./05-设计售前FDE">05-设计售前FDE</a></p>',14)])])}const _=e(s,[["render",l]]);export{u as __pageData,_ as default};
